// Calls for the endpoints in docs/API_CONTRACT.md. Engine request/response models are aliases of the types generated
// from the engine's OpenAPI schema (`npm run gen:api` → schema.d.ts); only artifacts served as files (slice-stack meta,
// model/*.json) and not-yet-exported routes are typed by hand here or in viewer3d/types.ts.
//
// Dev-only mock: `npm run dev -- --mode mock` swaps every call for the synthetic phantom in `mock.ts`
// (data generated by `node scripts/make-mock-study.mjs`). The mock module is tree-shaken from real builds.
import { api, ApiError, watchJob, type JobInfo, type ProgressEvent } from './client'
import type { components } from './schema'
import type { Knowledge, ModelStatus, RegionsJson, StatsJson } from '../viewer3d/types'

export type { JobInfo, ProgressEvent }

export const MOCK = import.meta.env.MODE === 'mock'
const mock = () => import('./mock')

// ---------- engine models: generated from the engine's OpenAPI schema (`npm run gen:api`) ----------
type S = components['schemas']
/** Request bodies: fields the engine defaults are optional for the caller. */
type In<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>

// §1 choosing what to import
export type FsRoot = S['Root']
export type FsRootKind = FsRoot['kind']
export type FsHint = 'dicomdir' | 'dcmburner' | 'radiant' | (string & {})
export type FsEntry = S['Entry']
export type FsListing = In<S['Listing'], 'truncated'>
export type InspectResult = S['InspectOut']

// §2 import job
export type ImportRequest = In<S['ImportIn'], 'remember'>
export type ImportErrorCode = 'password_required' | 'wrong_password' | 'no_images' | 'unsupported' | 'too_large'
export const IMPORT_STAGES = ['detect', 'decrypt', 'extract', 'scan', 'group', 'classify', 'export'] as const
export type ImportStage = (typeof IMPORT_STAGES)[number]

// §3 study
export type SeriesInfo = S['SeriesInfo']
export type Plane = SeriesInfo['plane']
export type Role = SeriesInfo['role']
export type Region = 'brain' | 'spine' | 'chest' | 'abdomen' | 'limb' | 'vessels' | 'unknown'
export type StudyInfo = S['StudyInfo']
/** `GET /api/studies` returns full StudyInfo rows; the list UI needs only these fields (the dev mock adds `n_series`). */
export type StudySummary = Pick<StudyInfo, 'id' | 'description' | 'study_date' | 'modalities'> & Partial<Pick<StudyInfo, 'adapter' | 'series'>> & { n_series?: number }

// ---------- served files (not OpenAPI models: written by the engine into the study folder) ----------
/** `series/{id}/meta.json` — the slice-stack artifact. */
export interface SeriesMeta {
  id: string
  title: string
  modality: string
  sequence: string
  plane: Plane | 'mip' | string
  region: Region | string
  role: Role | string
  n: number
  ext: string
  w: number
  h: number
  rows: number
  cols: number
  /** DICOM order [row, col] mm; null for photos / PDF pages. */
  pixelSpacing: [number, number] | null
  thickness: number | null
  TE?: number | null
  TR?: number | null
  seriesNumber?: number | null
  desc?: string
  orientation: number[] | null
  slices: { pos: [number, number, number] | null }[]
  window?: { lo: number; hi: number }
  labels: boolean
  /** Not in contract v1: optional code → name map. Real names arrive with M2 atlases. */
  labelNames?: Record<string, string>
  /** M2 (contract §5): label code → region key (`L|hippocampus`). */
  labelTable?: Record<string, string>
}

// ---------- calls ----------
const enc = encodeURIComponent

export async function fsRoots(): Promise<FsRoot[]> {
  return MOCK ? (await mock()).mockRoots() : api.get<FsRoot[]>('/api/fs/roots')
}
export async function fsList(path: string): Promise<FsListing> {
  return MOCK ? (await mock()).mockList(path) : api.get<FsListing>(`/api/fs/list?path=${enc(path)}`)
}
export async function inspect(path: string): Promise<InspectResult> {
  return MOCK ? (await mock()).mockInspect(path) : api.post<InspectResult>('/api/inspect', { path })
}
export async function startImport(body: ImportRequest): Promise<JobInfo> {
  return MOCK ? (await mock()).mockImport(body) : api.post<JobInfo>('/api/import', body)
}
export async function cancelJob(id: string): Promise<void> {
  if (MOCK) return (await mock()).mockCancel(id)
  await api.cancelJob(id)
}
/** Subscribe to job progress (SSE). Returns an unsubscribe function. */
export function watch(id: string, onEvent: (e: ProgressEvent) => void, onEnd: (j: JobInfo) => void): () => void {
  if (!MOCK) return watchJob(id, onEvent, onEnd)
  let stop: (() => void) | null = null
  let dead = false
  mock().then((m) => { if (!dead) stop = m.mockWatch(id, onEvent, onEnd) })
  return () => { dead = true; stop?.() }
}

export async function listStudies(): Promise<StudySummary[]> {
  return MOCK ? (await mock()).mockStudies() : api.get<StudySummary[]>('/api/studies')
}
export async function getStudy(id: string): Promise<StudyInfo> {
  return MOCK ? (await mock()).mockStudy(id) : api.get<StudyInfo>(`/api/studies/${enc(id)}`)
}
export async function deleteStudy(id: string): Promise<void> {
  if (MOCK) return
  await api.del(`/api/studies/${enc(id)}`)
}

/** URL of a study artifact file (`relpath` like `series/s003/meta.json`). */
export function fileUrl(studyId: string, relpath: string): string {
  const rel = relpath.split('/').map(enc).join('/')
  return MOCK ? `/mock/studies/${enc(studyId)}/files/${rel}` : `/api/studies/${enc(studyId)}/files/${rel}`
}
/** Image file name for slice `i` (`000.webp`) or its label map (`L000.png`). */
export const sliceName = (i: number, ext: string) => `${String(i).padStart(3, '0')}.${ext}`
export const labelName = (i: number) => `L${String(i).padStart(3, '0')}.png`

const metaCache = new Map<string, Promise<SeriesMeta>>()
export function getSeriesMeta(studyId: string, seriesId: string): Promise<SeriesMeta> {
  const url = fileUrl(studyId, `series/${seriesId}/meta.json`)
  let p = metaCache.get(url)
  if (!p) {
    p = fetch(url, { credentials: 'same-origin' }).then((r) => {
      if (!r.ok) throw new Error(`meta ${r.status}`)
      return r.json() as Promise<SeriesMeta>
    })
    p.catch(() => metaCache.delete(url))
    metaCache.set(url, p)
  }
  return p
}

// ---------- §5 3D model (M2) ----------
export type { Knowledge, ModelStatus, RegionsJson, StatsJson }

/** Model pipeline stages the UI has friendly names for (unknown stages fall back to a generic label). */
export const MODEL_STAGES = ['plan', 'load', 'fuse', 'skullstrip', 'segment', 'register', 'surface', 'label', 'decimate', 'measure', 'thumbs', 'export'] as const

async function getFileJSON<T>(studyId: string, rel: string): Promise<T | null> {
  const r = await fetch(fileUrl(studyId, rel), { credentials: 'same-origin' })
  if (r.status === 404) return null
  if (!r.ok) throw new Error(`${rel}: HTTP ${r.status}`)
  if (!(r.headers.get('content-type') ?? '').includes('json')) return null // e.g. SPA fallback page
  return r.json() as Promise<T>
}

/** `model/status.json`, or null when no model has been built yet. */
export async function getModelStatus(studyId: string): Promise<ModelStatus | null> {
  if (MOCK && !(await mock()).mockModelBuilt(studyId)) return null
  return getFileJSON<ModelStatus>(studyId, 'model/status.json')
}
export const getRegions = (studyId: string) => getFileJSON<RegionsJson>(studyId, 'model/regions.json')
export const getStats = (studyId: string) => getFileJSON<StatsJson>(studyId, 'model/stats.json')
export const modelUrl = (studyId: string) => fileUrl(studyId, 'model/scene.glb')

// ---------- §6 model options (M3) ----------
export type PipelineId = 'auto' | 'brain_mr' | 'ct_body' | 'vessels' | 'spine_mr' | (string & {})
/** Backends the engine accepts (generated `ModelIn.backend`). */
export type BackendId = S['ModelIn']['backend']
export interface BackendOption { id: string; available: boolean; reason: string | null; licence: string | null; default: boolean }
export interface PipelineOption { pipeline: PipelineId; score: number; reason: string | null; backends: BackendOption[] }
export interface ModelOptions { pipelines: PipelineOption[]; recommended: PipelineId | null }

/** POST body of `/api/studies/{id}/model` (generated `ModelIn`). */
export type ModelRequest = In<S['ModelIn'], 'pipeline' | 'backend'>
/** Engine response of `GET …/model/options` (generated); read through `normaliseOptions`. */
export type EngineModelOptions = S['ModelOptions']
const BACKENDS: readonly string[] = ['auto', 'classical', 'totalseg'] satisfies BackendId[]

type Raw = Record<string, unknown>
const isRec = (v: unknown): v is Raw => !!v && typeof v === 'object' && !Array.isArray(v)
const str = (v: unknown): string | null => (typeof v === 'string' && v ? v : null)
function normBackends(raw: unknown): BackendOption[] {
  const list: [string, unknown][] = Array.isArray(raw)
    ? raw.map((b) => [typeof b === 'string' ? b : str((b as Raw)?.id) ?? str((b as Raw)?.name) ?? str((b as Raw)?.backend) ?? '', b])
    : isRec(raw) ? Object.entries(raw) : []
  return list.filter(([id]) => !!id).map(([id, b]) => {
    const r = isRec(b) ? b : {}
    return {
      id, available: r.available !== false && r.installed !== false,
      reason: str(r.reason) ?? str(r.note) ?? str(r.message), licence: str(r.licence) ?? str(r.license), default: r.default === true,
    }
  })
}
/**
 * Tolerant reader for `GET /api/studies/{id}/model/options` (contract §6 names the content, not the exact shape):
 * accepts the engine's `{auto, options: [...]}`, `{pipelines: [...], backends?, recommended?}` or a bare pipeline array; pipelines as objects
 * (`name|pipeline|id`, `score`, `backends`) or strings; backends as string ids, objects or an id → info map.
 * Pipelines are sorted by score (best first); zero-score pipelines are dropped.
 */
export function normaliseOptions(raw: unknown): ModelOptions {
  const root: Raw = Array.isArray(raw) ? { pipelines: raw } : isRec(raw) ? raw : {}
  const shared = normBackends(root.backends)
  const pl: PipelineOption[] = []
  const list = root.pipelines ?? root.options // engine: `{auto, options: [{pipeline, score, backends: [ids usable now]}]}`
  const src = Array.isArray(list) ? list : isRec(list) ? Object.entries(list).map(([k, v]) => ({ name: k, ...(isRec(v) ? v : { score: v }) })) : []
  for (const p of src) {
    const r: Raw = typeof p === 'string' ? { name: p, score: 1 } : isRec(p) ? p : {}
    const id = str(r.pipeline) ?? str(r.name) ?? str(r.id)
    const score = typeof r.score === 'number' && Number.isFinite(r.score) ? r.score : r.applies === true ? 1 : 0.5
    if (!id || score <= 0) continue
    const own = r.backends !== undefined ? normBackends(r.backends) : shared
    pl.push({ pipeline: id, score, reason: str(r.reason) ?? str(r.why), backends: own })
  }
  pl.sort((a, b) => b.score - a.score)
  const rec = str(root.recommended) ?? str(root.default) ?? str(root.auto)
  return { pipelines: pl, recommended: rec && pl.some((p) => p.pipeline === rec) ? rec : pl[0]?.pipeline ?? null }
}

/** Model options for a study, or null when the engine has no options route (older engine → build with `auto`). */
export async function getModelOptions(studyId: string): Promise<ModelOptions | null> {
  if (MOCK) { const raw = await (await mock()).mockModelOptions(studyId); return raw == null ? null : normaliseOptions(raw) }
  try {
    return normaliseOptions(await api.get<EngineModelOptions>(`/api/studies/${enc(studyId)}/model/options`))
  } catch (e) {
    if (e instanceof ApiError && (e.status === 404 || e.status === 405 || e.status === 501)) return null
    throw e
  }
}

export async function startModel(studyId: string, pipeline: PipelineId = 'auto', backend?: string): Promise<JobInfo> {
  // only send a backend the engine's schema knows (older engines ignore/omit it)
  const body: ModelRequest = { pipeline, ...(backend && backend !== 'auto' && BACKENDS.includes(backend) ? { backend: backend as BackendId } : {}) }
  return MOCK ? (await mock()).mockStartModel(studyId, body) : api.post<JobInfo>(`/api/studies/${enc(studyId)}/model`, body)
}

const kbCache = new Map<string, Promise<Knowledge | null>>()
/** Generic anatomy knowledge base for `lang` (null if the engine doesn't serve one). */
export function getKnowledge(lang = 'en'): Promise<Knowledge | null> {
  let p = kbCache.get(lang)
  if (!p) {
    p = (MOCK ? mock().then((m) => m.mockKnowledge(lang)) : api.get<Knowledge>(`/api/knowledge?lang=${enc(lang)}`))
      .catch(() => null)
    kbCache.set(lang, p)
  }
  return p
}

// ---------- §7 optional model downloads (T7.7) ----------
export type ModelsInfo = S['ModelsOut']
export type ModelBundle = S['ModelBundleOut']
export type BrainModels = S['BrainModels']

/** Bundles (installed state, sizes, hosts, licences) — local only, no network. */
export async function getModels(): Promise<ModelsInfo> {
  return MOCK ? (await mock()).mockModels() : api.get<ModelsInfo>('/api/models')
}
/** Start downloading a bundle (the only outbound network the app makes; explicit user action only). */
export async function pullModels(bundle: string): Promise<JobInfo> {
  return MOCK ? (await mock()).mockPull(bundle) : api.post<JobInfo>('/api/models/pull', { bundle } satisfies S['PullIn'])
}
